// first-person-movement.js
var FirstPersonMovement = pc.createScript('firstPersonMovement');

FirstPersonMovement.attributes.add('camera', {
    type: 'entity',
    description: 'Optional, assign a camera entity, otherwise one is created'
});

FirstPersonMovement.attributes.add('power', {
    type: 'number',
    default: 2500,
    description: 'Adjusts the speed of player movement'
});

FirstPersonMovement.attributes.add('lookSpeed', {
    type: 'number',
    default: 0.25,
    description: 'Adjusts the sensitivity of looking'
});

// initialize code called once per entity
FirstPersonMovement.prototype.initialize = function() {
    this.force = new pc.Vec3();
    this.eulers = new pc.Vec3();
    
    var app = this.app;
    
    // Listen for mouse move events
    app.mouse.on("mousemove", this._onMouseMove, this);

    // when the mouse is clicked hide the cursor
    app.mouse.on("mousedown", function () {
        app.mouse.enablePointerLock();
    }, this);            

    // Check for required components
    if (!this.entity.collision) {
        console.error("First Person Movement script needs to have a 'collision' component");
    }

    if (!this.entity.rigidbody || this.entity.rigidbody.type !== pc.BODYTYPE_DYNAMIC) {
        console.error("First Person Movement script needs to have a DYNAMIC 'rigidbody' component");
    }
};

// update code called every frame
FirstPersonMovement.prototype.update = function(dt) {
    // If a camera isn't assigned from the Editor, create one
    if (!this.camera) {
        this._createCamera();
    }
    
    var force = this.force;
    var app = this.app;

    // Get camera directions to determine movement directions
    var forward = this.camera.forward;
    var right = this.camera.right;
       

    // movement
    var x = 0;
    var z = 0;

    // Use W-A-S-D keys to move player
    // Check for key presses
    if (app.keyboard.isPressed(pc.KEY_A) || app.keyboard.isPressed(pc.KEY_Q)) {
        x -= right.x;
        z -= right.z;
    }

    if (app.keyboard.isPressed(pc.KEY_D)) {
        x += right.x;
        z += right.z;
    }

    if (app.keyboard.isPressed(pc.KEY_W)) {
        x += forward.x;
        z += forward.z;
    }

    if (app.keyboard.isPressed(pc.KEY_S)) {
        x -= forward.x;
        z -= forward.z;
    }

    // use direction from keypresses to apply a force to the character
    if (x !== 0 && z !== 0) {
        force.set(x, 0, z).normalize().scale(this.power);
        this.entity.rigidbody.applyForce(force);
    }

    // update camera angle from mouse events
    this.camera.setLocalEulerAngles(this.eulers.y, this.eulers.x, 0);
};

FirstPersonMovement.prototype._onMouseMove = function (e) {
    // If pointer is disabled
    // If the left mouse button is down update the camera from mouse movement
    if (pc.Mouse.isPointerLocked() || e.buttons[0]) {
        this.eulers.x -= this.lookSpeed * e.dx;
        this.eulers.y -= this.lookSpeed * e.dy;
    }            
};

FirstPersonMovement.prototype._createCamera = function () {
    // If user hasn't assigned a camera, create a new one
    this.camera = new pc.Entity();
    this.camera.setName("First Person Camera");
    this.camera.addComponent("camera");
    this.entity.addChild(this.camera);
    this.camera.translateLocal(0, 0.5, 0);
};

// animation-scale.js
// More information about curves can be found at: 
// http://developer.playcanvas.com/en/user-manual/scripting/script-attributes/
// http://developer.playcanvas.com/en/api/pc.Curve.html

var AnimateCurve = pc.createScript('animateCurve');

// Example of creating curve attribute with as single curve
AnimateCurve.attributes.add("offsetCurve", {type: "curve", title: "Offset Curve"});
AnimateCurve.attributes.add("duration", {type: "number", default: 1, title: "Duration (secs)"});


// initialize code called once per entity
AnimateCurve.prototype.initialize = function() {
    // Keep track of the original scale of the entity
    this.startScale = this.entity.getLocalScale().clone();
    
    // Keep track of the current scale
    this.scale = new pc.Vec3();
    
    this.time = 0;
};


// update code called every frame
AnimateCurve.prototype.update = function(dt) {
    // Loop the animation forever
    this.time += dt;
    if (this.time > this.duration) {
        this.time -= this.duration;
    }
    
    // Calculate how far in time we are for the animation
    var percent = this.time / this.duration;
       
    // Get curve values using current time relative to duration (percent)
    var curveValue = this.offsetCurve.value(percent);
    
    // Create our new scale from the startScale and offset from the curve value
    this.scale.copy(this.startScale);
    this.scale.x += curveValue;
    this.scale.y += curveValue;
    this.scale.z += curveValue;
    
    this.entity.setLocalScale(this.scale);
};


// AnimationTrigger.js
var AnimationTrigger = pc.createScript('animationTrigger');
AnimationTrigger.prototype.initialize = function() {
    for(let i =0;i<this.triggerEntities.length;i++){
        this.triggerEntities[i].collision.on('triggerenter', this.onTriggerEnter, this);
    }
};
AnimationTrigger.prototype.onTriggerEnter = function (entity){
    for(let i =0;i<this.animatingEntities.length;i++){
        const animator = this.animatingEntities[i].anim;
        if(!animator){
            console.warn(`animator is missing on ${this.animatingEntity.name}`);
            return;
        }
        if(this.objectTags===""){
                this.playAnimation(animator);
        }
        else{
            if (entity.tags.has(this.objectTags)){
               this.playAnimation(animator);
            }
        }
 
    }
};
AnimationTrigger.prototype.playAnimation = function (animator){
     animator.baseLayer.transition(this.stateName, this.blendValue);  
};
AnimationTrigger.attributes.add('blendValue', {
    type: 'number',
    description:"fill in an blendValue between 0-1",
    default:0.2
});
AnimationTrigger.attributes.add('stateName', {
    type: 'string'
});
AnimationTrigger.attributes.add('objectTags', {
    type: 'string'
});
AnimationTrigger.attributes.add('animatingEntities', {
    type: 'entity',
    array: true
});
AnimationTrigger.attributes.add('triggerEntities', {
    type: 'entity',
    array:true
});



// animEventEntityToggler.js
var AnimEventEntityToggler = pc.createScript('animEventEntityToggler');


AnimEventEntityToggler.prototype.initialize = function() {
    this.animatingEntity.script=this.entity.script;
    this.app.on("eventDoor", this.toggleDoorTrigger,this);
     this.animatingEntity.anim.on(this.eventName, function (event) {
         this.entity.script.animEventEntityToggler.app.fire("eventDoor",event.string,this.entity.name);
    }), this;
};
AnimEventEntityToggler.prototype.toggleDoorTrigger = function(stringBool,eventEntityName) {
    if(eventEntityName!==this.animatingEntity.name)
        return;

    let enableEntity=true;

    if(stringBool){
        if(stringBool===this.stringEnable){
            enableEntity=true;
        }
        else{
            enableEntity=false;
        }
    }
    else{
        enableEntity=false;
    }


    if(this.entityToToggle){ 
        for(let i = 0 ;i<this.entityToToggle.length;i++){
            if(this.entityToToggle[i]!==null){
            this.entityToToggle[i].enabled = enableEntity;
            }
        }
    }
};

AnimEventEntityToggler.attributes.add('eventName', {
    type: 'string',
});
AnimEventEntityToggler.attributes.add('stringEnable', {
    type: 'string',
    default:"enabled",
    description:'this is an string that wil be check if the entity can be set to true or false if the animEvent wil send an string that is equal to stringEnable'
});

AnimEventEntityToggler.attributes.add('animatingEntity', {
    type: 'entity',
});
AnimEventEntityToggler.attributes.add('entityToToggle', {
    type: 'entity',
    array: true
});

// entity-rotator.js
const EntityRotator = pc.createScript('EntityRotator');
const _tempVec3 = new pc.Vec3();
const _tempQuat = new pc.Quat();

EntityRotator.attributes.add("useLocalRotation", {
    type: "boolean",
    default: false
});

EntityRotator.prototype.initialize = function() {
    const rotation = this.getRotation();
    this._rotationEuler = rotation.getEulerAngles();
};

EntityRotator.prototype.update = function(dt) {
    const rotationEuler = this._rotationEuler;
    _tempVec3.copy(this.degreesPerSecond);
    _tempVec3.mulScalar(dt);
    rotationEuler.add(_tempVec3);
    rotationEuler.x %= 360;
    rotationEuler.y %= 360;
    rotationEuler.z %= 360;
    
    _tempQuat.setFromEulerAngles(rotationEuler.x, rotationEuler.y, rotationEuler.z);

    if (this.useLocalRotation) {
        this.entity.setLocalRotation(_tempQuat);
    } else {
        this.entity.setRotation(_tempQuat);
    }
};

EntityRotator.prototype.getRotation = function() {
    return this.useLocalRotation ? this.entity.getLocalRotation() : this.entity.getRotation();
};

EntityRotator.prototype.setRotation = function(rotation) {
    if (this.useLocalRotation) {
        this.entity.setLocalRotation(rotation);
    } else {
        this.entity.setRotation(rotation);
    }
};

EntityRotator.attributes.add("degreesPerSecond", {
    type: "vec3"
});


// rigidbody-rotator.js
const RigidbodyRotator = pc.createScript('RigidbodyRotator');

RigidbodyRotator.prototype.initialize = function() {
    
};

RigidbodyRotator.prototype.update = function(dt) {
    const rigidbody = this.entity.rigidbody;
    const angularVelocity = rigidbody.angularVelocity;
    angularVelocity.copy(this.degreesPerSecond).mulScalar(pc.math.DEG_TO_RAD);
    rigidbody.angularVelocity = angularVelocity;
};

RigidbodyRotator.attributes.add("degreesPerSecond", {
    type: "vec3"
});

