// BasketballScoreTrigger.js
// BasketballScoreTrigger.js

var BasketballScoreTrigger = pc.createScript('basketballScoreTrigger');

BasketballScoreTrigger.attributes.add('scoreDisplayEntity', {
    type: 'entity',
    title: 'Score Display Entity',
    description: 'The entity that has the BasketballScoreDisplay.js script.'
});

BasketballScoreTrigger.attributes.add('scoreTag', {
    type: 'string',
    default: 'basketball',
    title: 'Tag to Score',
    description: 'Only entities with this tag will trigger a score.'
});

BasketballScoreTrigger.attributes.add('cooldown', {
    type: 'number',
    default: 2,
    title: 'Cooldown (seconds)',
    description: 'Time in seconds before another score can be registered.'
});

// --- Initialize Code ---
BasketballScoreTrigger.prototype.initialize = function() {
    this.canScore = true;
    
    // The Y-axis position of the hoop's trigger. This is our "scoring plane".
    this.hoopPlaneY = this.entity.getPosition().y;

    // We will use a Map to keep track of all potential scoring objects
    // currently inside our trigger, along with their last frame's Y position.
    this.objectsInTrigger = new Map();

    // Listen for both entering and leaving the trigger
    this.entity.collision.on('triggerenter', this.onTriggerEnter, this);
    this.entity.collision.on('triggerleave', this.onTriggerLeave, this);
};

// --- On Trigger Enter ---
BasketballScoreTrigger.prototype.onTriggerEnter = function(otherEntity) {
    // If the entering entity is a basketball, add it to our tracking Map.
    if (otherEntity.tags.has(this.scoreTag)) {
        // We store the entity as the key and its current Y position as the value.
        this.objectsInTrigger.set(otherEntity, otherEntity.getPosition().y);
    }
};

// --- On Trigger Leave ---
BasketballScoreTrigger.prototype.onTriggerLeave = function(otherEntity) {
    // When an entity leaves, remove it from our tracking Map.
    if (this.objectsInTrigger.has(otherEntity)) {
        this.objectsInTrigger.delete(otherEntity);
    }
};

// --- Update is called once per frame ---
BasketballScoreTrigger.prototype.update = function(dt) {
    // If we are on cooldown, don't check for scores.
    if (!this.canScore) {
        return;
    }

    // Loop through all the objects currently in our trigger.
    for (const [entity, lastY] of this.objectsInTrigger.entries()) {
        const currentY = entity.getPosition().y;

        // THE SCORING LOGIC:
        // A score is counted if the object was ABOVE the hoop plane in the
        // last frame and is now AT OR BELOW the hoop plane in the current frame.
        if (lastY > this.hoopPlaneY && currentY <= this.hoopPlaneY) {
            
            // Tell the score display to increment.
            if (this.scoreDisplayEntity && this.scoreDisplayEntity.script.basketballScoreDisplay) {
                this.scoreDisplayEntity.script.basketballScoreDisplay.incrementScore();
            }

            // Start the cooldown.
            this.canScore = false;
            setTimeout(() => {
                this.canScore = true;
            }, this.cooldown * 1000);

            // IMPORTANT: Remove the object from the map immediately after scoring
            // to prevent it from scoring again in the next frame.
            this.objectsInTrigger.delete(entity);

            // Exit the loop since we've just scored.
            break; 
        } else {
            // If no score, update the object's "lastY" position for the next frame's check.
            this.objectsInTrigger.set(entity, currentY);
        }
    }
};


// BasketballScoreDisplay.js
// BasketballScoreDisplay.js

var BasketballScoreDisplay = pc.createScript('basketballScoreDisplay');

BasketballScoreDisplay.attributes.add('soundEffectEntity', {
    type: 'entity',
    title: 'Sound Effect Entity',
    description: 'The entity with the Sound component to play when a score is made.'
});

BasketballScoreDisplay.attributes.add('scoreKey', {
    type: 'string',
    default: 'basketball_score',
    title: 'Score Key',
    description: 'Unique identifier for storing this score in localStorage.'
});

BasketballScoreDisplay.attributes.add('scoreValue', {
    type: 'number',
    default: 1,
    title: 'Score Value',
    description: 'Points awarded when a score is made.'
});

// --- Initialize Code ---
BasketballScoreDisplay.prototype.initialize = function() {
    // Load score from localStorage
    this.score = this.loadScore();
    this.updateText();

    // Track if score changed this session
    this._dirty = false;

    // Auto-save only if dirty
    this._beforeUnloadHandler = () => {
        if (this._dirty) {
            this.saveScore();
        }
    };
    window.addEventListener('beforeunload', this._beforeUnloadHandler);
};

// --- Public function to increment score ---
BasketballScoreDisplay.prototype.incrementScore = function() {
    this.score += this.scoreValue;
    this.updateText();
    this.saveScore();   // Save immediately
    this._dirty = true; // Mark as changed

    // Play sound if available
    if (this.soundEffectEntity && this.soundEffectEntity.sound) {
        const slots = this.soundEffectEntity.sound.slots;
        if (slots && Object.keys(slots).length > 0) {
            const firstSlotName = Object.keys(slots)[0];
            this.soundEffectEntity.sound.play(firstSlotName);
        }
    }
};

// --- Internal function to update the text element ---
BasketballScoreDisplay.prototype.updateText = function() {
    const textElement = this.entity.element;
    if (textElement) {
        textElement.text = this.score.toString().padStart(4, '0');
    }
};

// --- Save score to localStorage ---
BasketballScoreDisplay.prototype.saveScore = function() {
    try {
        localStorage.setItem(this.scoreKey, this.score.toString());
        this._dirty = false; // Reset dirty flag once saved
    } catch (e) {
        console.warn('Could not save score to localStorage:', e);
    }
};

// --- Load score from localStorage ---
BasketballScoreDisplay.prototype.loadScore = function() {
    try {
        const savedScore = localStorage.getItem(this.scoreKey);
        return savedScore ? parseInt(savedScore, 10) : 0;
    } catch (e) {
        console.warn('Could not load score from localStorage:', e);
        return 0;
    }
};

// --- Cleanup to avoid leaks when entity is destroyed ---
BasketballScoreDisplay.prototype.onDestroy = function() {
    if (this._beforeUnloadHandler) {
        window.removeEventListener('beforeunload', this._beforeUnloadHandler);
        this._beforeUnloadHandler = null;
    }
};


// ui-video.js
var UiVideo = pc.createScript('uiVideo');

UiVideo.attributes.add('videoAsset', {
    type: 'asset',
    title: 'MP4 Asset'
});

UiVideo.prototype.initialize = function () {
    const el = this.entity.element;
    if (!el) {
        console.error('UiVideo: entity must have an Element component of type Image');
        return;
    }

    el.type = pc.ELEMENTTYPE_IMAGE;

    if (!this.videoAsset) {
        console.error('UiVideo: No MP4 asset assigned.');
        return;
    }

    // Create <video> element
    const video = document.createElement('video');
    video.src = this.videoAsset.getFileUrl();
    video.crossOrigin = 'anonymous';
    video.loop = true;
    video.muted = true;        // required for autoplay
    video.playsInline = true;  // iOS inline playback
    video.autoplay = true;
    video.preload = 'auto';

    // Make the texture and assign it to the image
    const texture = new pc.Texture(this.app.graphicsDevice, {
        format: pc.PIXELFORMAT_SRGB8,
        mipmaps: false
    });
    texture.setSource(video);
    texture.addressU = pc.ADDRESS_CLAMP_TO_EDGE;
    texture.addressV = pc.ADDRESS_CLAMP_TO_EDGE;

    el.texture = texture;

    // Store references for update
    this.video = video;
    this.texture = texture;

    // Try to start playback when possible
    const tryPlay = () => {
        const playPromise = video.play();
        if (playPromise !== undefined) {
            playPromise.catch(() => {}).then(() => {});
        }
    };

    video.addEventListener('canplay', tryPlay);
    window.addEventListener('touchend', tryPlay, { once: true });
    window.addEventListener('click', tryPlay, { once: true });
};

// Update texture every frame
UiVideo.prototype.update = function (dt) {
    if (this.video && this.texture) {
        // Force texture refresh (important on some browsers)
        this.texture.upload();
    }
};


// CountdownTimer.js
// countdownTimer.js

var CountdownTimer = pc.createScript('countdownTimer');

// --- Attributes ---
CountdownTimer.attributes.add('uiTextEntity', {
    type: 'entity',
    title: 'UI Text Entity',
    description: 'Entity with an Element component of type Text'
});

CountdownTimer.attributes.add('startSeconds', {
    type: 'number',
    default: 60,
    min: 0,
    title: 'Start Seconds'
});

CountdownTimer.attributes.add('autoStart', {
    type: 'boolean',
    default: true,
    title: 'Start Automatically'
});

CountdownTimer.attributes.add('format', {
    type: 'string',
    default: 'mm:ss',
    title: 'Display Format',
    description: 'Use "mm:ss" for minutes:seconds, or "s" to show raw seconds'
});

// --- Internal state ---
CountdownTimer.prototype.initialize = function () {
    this._original = Math.max(0, Math.floor(this.startSeconds || 0));
    this._remaining = this._original;
    this._accum = 0;
    this._running = false;
    this._warned = false;

    this._updateLabel();

    // Robust lifecycle hooks: handle both script and entity enable/disable paths
    this.on('enable', this._handleEnable, this);     // script enabled
    this.on('disable', this._handleDisable, this);   // script disabled

    // Also listen to entity events (covers parent toggles)
    this.entity.on('enable', this._handleEnable, this);
    this.entity.on('disable', this._handleDisable, this);

    if (this.autoStart && this.entity.enabled && this.enabled) {
        // ensure we begin only after initialize shows the initial value
        this.start();
    }
};

// Frame update
CountdownTimer.prototype.update = function (dt) {
    if (!this._running || this._remaining <= 0) return;

    this._accum += dt;

    // Tick once per whole second for stable UI updates
    while (this._accum >= 1 && this._remaining > 0) {
        this._accum -= 1;
        this._remaining--;

        this._updateLabel();

        if (this._remaining <= 0) {
            this._running = false;
            this.fire('done');
            this.app.fire('countdown:done', this.entity);
            break;
        }
    }
};

// --- Lifecycle handlers (centralized) ---
CountdownTimer.prototype._handleEnable = function () {
    // Hard reset any time this entity/script becomes enabled
    this.reset();
    if (this.autoStart) this.start();
};

CountdownTimer.prototype._handleDisable = function () {
    // Stop and pre-reset so a subsequent enable always starts from the original
    this.stop();
    this.reset();
};

// --- Public API ---
CountdownTimer.prototype.start = function () {
    // If someone changed startSeconds at runtime, honor the current _original
    if (this._remaining <= 0) this._remaining = this._original;
    this._running = true;
};

CountdownTimer.prototype.stop = function () {
    this._running = false;
};

CountdownTimer.prototype.reset = function () {
    this._remaining = this._original;
    this._accum = 0;
    this._running = false;
    this._updateLabel();
};

// Optionally set a new starting value at runtime (in seconds)
CountdownTimer.prototype.setStartSeconds = function (seconds, autoRestart) {
    this._original = Math.max(0, Math.floor(seconds || 0));
    this.reset();
    if (autoRestart) this.start();
};

// --- Helpers ---
CountdownTimer.prototype._updateLabel = function () {
    if (this.uiTextEntity && this.uiTextEntity.element) {
        this.uiTextEntity.element.text = this._formatTime(this._remaining);
    } else if (this.uiTextEntity && !this._warned) {
        console.warn('[CountdownTimer] The linked entity has no Element (Text). Add Element → Type: Text.');
        this._warned = true;
    }
};

CountdownTimer.prototype._formatTime = function (s) {
    if (this.format === 's') return String(s);

    var minutes = Math.floor(s / 60);
    var seconds = s % 60;
    var mm = minutes.toString();
    var ss = seconds < 10 ? '0' + seconds : '' + seconds;
    return mm + ':' + ss;
};


// ui-video-shared.js
// ui-video-shared.js
// Plays an MP4 picked in the Editor on a UI Image Element.
// Optimized: ONE shared <video> + ONE shared pc.Texture per "shareKey"
// and uploads only when a new frame arrives (requestVideoFrameCallback or throttled).

var UiVideoShared = pc.createScript('uiVideoShared');

UiVideoShared.attributes.add('videoAsset', { type: 'asset', title: 'MP4 Asset' });
UiVideoShared.attributes.add('shareKey',   { type: 'string', default: 'tvPreview' });
UiVideoShared.attributes.add('targetFps',  { type: 'number', default: 12, min: 1, max: 60 });

// Global pool: { key: { video, texture, refs, started, rAF, lastUpload } }
UiVideoShared._pool = UiVideoShared._pool || {};

UiVideoShared.prototype.initialize = function () {
    const el = this.entity.element;
    if (!el) { console.error('Needs an Element component of type Image'); return; }
    el.type = pc.ELEMENTTYPE_IMAGE;

    if (!this.videoAsset) { console.error('Assign an MP4 asset'); return; }

    const key = this.shareKey || 'tvPreview';
    let shared = UiVideoShared._pool[key];

    if (!shared) {
        const video = document.createElement('video');
        video.src = this.videoAsset.getFileUrl();
        video.crossOrigin = 'anonymous';
        video.loop = true;
        video.muted = true;          // autoplay on mobile
        video.playsInline = true;    // iOS inline playback
        video.autoplay = true;
        video.preload = 'auto';

        // Prefer sRGB for UI gamma if available, fall back to RGB8
        const fmt = (pc.PIXELFORMAT_SRGB8 !== undefined)
            ? pc.PIXELFORMAT_SRGB8
            : pc.PIXELFORMAT_R8_G8_B8;

        const texture = new pc.Texture(this.app.graphicsDevice, {
            format: fmt,
            mipmaps: false
        });
        texture.setSource(video);
        texture.addressU = texture.addressV = pc.ADDRESS_CLAMP_TO_EDGE;
        texture.minFilter = pc.FILTER_LINEAR;
        texture.magFilter = pc.FILTER_LINEAR;

        shared = UiVideoShared._pool[key] = {
            video,
            texture,
            refs: 0,
            started: false,
            rAF: null,
            lastUpload: 0
        };

        // Start playback on gesture if needed
        const tryPlay = () => video.play().catch(()=>{});
        video.addEventListener('canplay', tryPlay);
        window.addEventListener('touchend', tryPlay, { once: true });
        window.addEventListener('click',    tryPlay, { once: true });

        // Pause when tab hidden
        document.addEventListener('visibilitychange', () => {
            if (document.hidden) video.pause();
            else tryPlay();
        });

        // Frame-driven uploads
        const hasRVFC = typeof video.requestVideoFrameCallback === 'function';
        if (hasRVFC) {
            const onFrame = () => {
                texture.upload();                 // upload only when a new frame is decoded
                video.requestVideoFrameCallback(onFrame);
            };
            video.requestVideoFrameCallback(onFrame);
        } else {
            // Fallback throttle to target FPS (saves CPU vs. every-tick upload)
            const intervalMs = Math.max(1000 / (this.targetFps || 12), 15);
            shared.rAF = setInterval(() => texture.upload(), intervalMs);
        }
    }

    // Attach shared texture to this element
    el.texture = shared.texture;
    shared.refs++;

    // Cleanup on destroy
    this.on('destroy', () => {
        const s = UiVideoShared._pool[key];
        if (!s) return;
        s.refs--;
        if (s.refs <= 0) {
            try { s.video.pause(); } catch(e){}
            if (s.rAF) { clearInterval(s.rAF); s.rAF = null; }
            s.texture.destroy();
            delete UiVideoShared._pool[key];
        }
    });
};


